    color: var(--text-color);
    line-height: 1.5;
    margin: 0;
    padding: 2rem 1rem;
    display: flex;
    flex-direction: column;
    align-items: center;
}

header {
    margin-bottom: 2rem;
    text-align: center;
}

h1 {
    font-size: 2rem;
    font-weight: 700;
    margin: 0;
}

main {
    width: 100%;
    max-width: 600px;
}

form {
    background: var(--card-bg);
    padding: 2rem;
    border-radius: 0.75rem;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.form-field {
    margin-bottom: 2rem;
}

fieldset {
    border: none;
    padding: 0;
    margin: 0;
}

legend {
    font-weight: 600;
    font-size: 1.125rem;
    margin-bottom: 0.5rem;
    display: block;
    width: 100%;
}

.help-text {
    font-size: 0.875rem;
    color: var(--text-muted);
    margin: 0 0 1rem 0;
}

.options {
    display: grid;
    gap: 0.75rem;
}

.option {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem;
    border: 1px solid var(--border-color);
    border-radius: 0.5rem;
    transition: background-color 0.2s, border-color 0.2s;
    cursor: pointer;
}

.option:hover {
    background-color: #f1f5f9;
}

.option:has(input:focus-visible) {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

input[type="checkbox"] {
    width: 1.25rem;
    height: 1.25rem;
    accent-color: var(--primary-color);
    cursor: pointer;
}

label {
    cursor: pointer;
    flex-grow: 1;
    font-weight: 500;
}

.form-actions {
    margin-top: 2rem;
}

button {
    background-color: var(--primary-color);
    color: white;
    border: none;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 0.5rem;
    cursor: pointer;
    width: 100%;
    transition: background-color 0.2s;
}

button:hover {
    background-color: var(--primary-hover);
}

button:focus-visible {
    outline: none;
    box-shadow: var(--focus-ring);
}

.result-area {
    margin-top: 1.5rem;
    padding: 1rem;
    border-radius: 0.5rem;
    font-weight: 600;
    text-align: center;
}

.result-success {
    background-color: #f0fdf4;
    color: var(--success-color);
    border: 1px solid #bbf7d0;
}

.result-partial {
    background-color: #fffbeb;
    color: #92400e;
    border: 1px solid #fef3c7;
}

.result-error {
    background-color: #fef2f2;
    color: var(--error-color);
    border: 1px solid #fecaca;
}

@media (max-width: 480px) {
    body {
        padding: 1rem;
    }
    form {
        padding: 1.5rem;
    }
}
