  const filePath = 'file://' + path.resolve('index.html');
  await page.goto(filePath, { waitUntil: 'networkidle' });

  const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
  await page.evaluate(axeSource);

  const resultsInitial = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await page.click('button[type="submit"]');

  const resultsResult = await page.evaluate(async () => {
    return await window.axe.run();
  });

  const allViolations = [...resultsInitial.violations, ...resultsResult.violations];

  const wcag = allViolations.filter(v => !v.tags.includes('best-practice'));
  const bp = allViolations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bp.map(v => ({
      id: v.id,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    }))
  }, null, 2));

  await browser.close();
  process.exit(wcag.length > 0 ? 1 : 0);
})();

