document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('quiz-form');
    const resultArea = document.getElementById('quiz-result');

    const correctAnswers = {
        q1: ['cpp', 'java'],
        q2: ['html', 'css', 'js'],
        q3: ['csharp', 'ts']
    };

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        const formData = new FormData(form);
        const userAnswers = {
            q1: formData.getAll('q1'),
            q2: formData.getAll('q2'),
            q3: formData.getAll('q3')
        };

        let score = 0;
        const totalQuestions = Object.keys(correctAnswers).length;

        for (const [question, correct] of Object.entries(correctAnswers)) {
            const user = userAnswers[question];

            // Check if user selected exactly the correct ones
            const isCorrect = user.length === correct.length && 
                              user.every(val => correct.includes(val));

            if (isCorrect) {
                score++;
            }
        }

        displayResult(score, totalQuestions);
    });

    function displayResult(score, total) {
        resultArea.innerHTML = '';
        resultArea.className = 'result-area'; // reset classes

        const scoreText = `You got ${score} out of ${total} questions right.`;
        let message = '';

        if (score === total) {
            resultArea.classList.add('result-success');
            message = `Excellent! ${scoreText}`;
        } else if (score > 0) {
            resultArea.classList.add('result-partial');
            message = `Not bad! ${scoreText}`;
        } else {
            resultArea.classList.add('result-error');
            message = `Keep learning! ${scoreText}`;
        }

        resultArea.textContent = message;

        // Scroll to result for visibility
        resultArea.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
});
